CREATE OR REPLACE FUNCTION ECAMS.GET_DIFFYN
(SYSCD varchar2,
 DSNCD varchar2)
return VARCHAR2
IS
   V_MSG       VARCHAR2(10);
   V_DIRPATH   CMM0070.CM_DIRPATH%TYPE;
   VCNT        NUMBER;


BEGIN
      V_MSG := 'N';

      BEGIN
          SELECT /*+ RULE */
                 COUNT(*)
            INTO VCNT
            FROM CMM0029
           WHERE CM_STNO='ECAMS'
             AND CM_GBNCD='01'
             AND CM_SYSCD=SYSCD
             AND CM_DSNCD=DSNCD;
          EXCEPTION
             WHEN  NO_DATA_FOUND  Then
